  replies_line: (f) => `💬 پاسخ‌ها برای شما: +$${f}.`,
  err_ai: 'هوش مصنوعی اکنون نتوانست نسخه معتبر بسازد. دوباره تلاش کنید یا متن خودتان را نگه دارید.',
  test_ok: (left, ch) => `🧪 آزمایش در صف است — ظرف یک دقیقه می‌رسد. ${ch ? `${money(ch)} از کیف پول کسر شد (با رزرو کمپین برمی‌گردد). ` : ''}${left} آزمایش باقی مانده.`,
  err_test_quota: (d, w) => `سقف آزمایش پر شد: ${d} در روز / ${w} در هفته برای همه کمپین‌ها. کمپین را رزرو کنید یا فردا امتحان کنید.`,
  err_content_changed: 'متن پس از آزمایش تغییر کرده. ابتدا آزمایش جدید بفرستید.',
  n_test_refund: (name, a) => `↩️ کمپین «${name}» رزرو شد — ${money(a)} هزینه آزمایش به کیف پول شما برگشت.`,
