  err_add_text: 'متن پیام را بنویسید.',
  err_too_long: (m) => `خیلی طولانی: هر نسخه باید یک پیامک باشد — حداکثر ${m} نویسه${m < 160 ? ' (بقیه را خط لغو می‌گیرد)' : ''}. کوتاهش کنید.`,
  err_special_char: (c) => `یک نویسه محدودیت را بسیار کوتاه می‌کند (۷۰ به‌جای ۱۶۰ در هر پیامک). آن را با یک حرف معمولی جایگزین کنید: ${c}. این اغلب هنگام کپی‌کردن متن رخ می‌دهد.`,
  err_has_link: 'پیام شما لینک یا شماره تلفن دارد. آن را حذف کنید، یا برگردید و «با لینک یا شماره تلفن» را انتخاب کنید.',
  err_consent: 'لطفاً تأیید کنید مخاطبان با دریافت پیامک موافق‌اند.',
  err_few: (min, n) => `فقط ${n} پیامک — هر کمپین حداقل ${min} لازم دارد.`,
  err_campaign: 'کمپین پیدا نشد.',
  err_number: 'یک شماره موبایل آمریکا یا کانادا وارد کنید: +1 و ۱۰ رقم.',
