    progress_line: (name, st, r) => `📈 <b>${name}</b> — ${st}\n   ${r.sent}/${r.total} sent · ${r.failed} failed · ${r.rejected} not sent · ${r.queued} waiting · ${r.replies} replies${r.skipped ? ` · ${r.skipped} skipped (not mobile)` : ''} · ${r.successPct}% success`,
    n_done: (name, s, f, r, rp, sk, rf, ll) => `🏁 Campaign “${name}” finished: ${s} sent, ${f} failed, ${r} not sent, ${rp} replies${sk ? `, ${sk} skipped by the number check${ll ? ` (${ll === sk ? 'all' : ll} landlines — they can’t receive texts, so you weren’t charged for them)` : ''}` : ''}.${rf ? ` ${money(rf)} for texts that couldn’t be sent is back in your wallet.` : ''}`,
    err_link_flagged: (l) => `⛔ <b>Content flagged.</b> Google reports this link as unsafe (phishing, malware or unwanted software): ${l}\nRemove or replace it to continue.`,
    err_link_flagged_all: 'Every version of this campaign contains a link Google flags as unsafe — it can’t be tested or booked.',
    err_link_unchecked: 'We couldn’t check your link’s safety just now. Try the test again in a few minutes.',
    n_link_flagged: (name, l, n, all) => `⛔ Campaign “${name}”: Google now flags ${l} as unsafe. ${n} text(s) with it were stopped — no refund for texts with flagged links.${all ? ' The campaign has stopped.' : ' Your other versions keep sending.'}`,
    err_free_number_used: 'That number already received a free test. Use another number, or top up to test again.',
    err_free_cap: 'Free tests are paused for today. Top up your wallet to test now, or try tomorrow.',
