    review: (o) => `👀 <b>Votre message</b>${(o.v || []).length > 1 ? ` — ${(o.v || []).length} versions alternées` : ''}\n${numbered(o.v || [])}\n${o.optOut ? '+ « Reply STOP to opt out »' : 'Sans ligne de désinscription'}\n\n${o.links ? `🔗 Avec lien / numéro${o.found?.length ? ` (trouvé : ${o.found.join(', ')})` : ''}` : '📝 Texte seul'} · ${o.n} numéros · <b>${o.price} $</b>\n\nL’envoyer tel quel, ou alterner des versions pour mieux passer les filtres des opérateurs ?`,
    ai_links_q: '🔗 L’IA garde votre lien / numéro exactement tel quel.\nUn lien ou numéro différent pour chaque version ? Envoyez-les, un par ligne (10 max). Ou gardez le même.',
    err_links_bad: 'Chaque ligne doit être un lien ou un numéro de téléphone.',
    ready: (o) => `✅ <b>Campagne prête</b> · ${o.n} numéros · ${o.v} version(s) · <b>${o.price} $</b>\n\n🧪 <b>Étape 3 sur 4 — Test (facultatif)</b>\n${o.free ? `🎁 Votre première campagne a droit à <b>1 test gratuit</b> vers n’importe quel numéro USA/Canada — sans portefeuille. Ensuite, les tests se débloquent quand votre portefeuille couvre une campagne : jusqu’à ${o.perDay} par jour, ${money(o.unit)} chacun, remboursé à la réservation.` : `Envoyez-le à n’importe quel numéro USA/Canada. Chaque test coûte ${money(o.unit)}, remboursé à la réservation. Jusqu’à ${o.tests} par campagne, ${o.perDay} par jour.`}`,
    test_to_q: (free) => `📞 Numéro pour le test${free ? ' gratuit' : ''} (USA/Canada, ex. +12125550123) :`,
